wr17SourceSection:
/* P3-WR-17: at 150 and 200% text the entry total moves under the entry, so "In progress" and "3h 3m" stay inside the card. */
@media (max-width: 760px), (max-width: 900px) and (max-height: 430px) and (orientation: landscape) and (pointer: coarse) {
  html:is([data-text-step="150"], [data-text-step="200"]) body .app-shell.nevora-portal[data-employee-corporate="true"] .page-frame .employee-time-entry > summary:not(#nv-kit) { grid-template-columns: minmax(0, 1fr) var(--corporate-space-6, 24px); }
  html:is([data-text-step="150"], [data-text-step="200"]) body .app-shell.nevora-portal[data-employee-corporate="true"] .page-frame .employee-time-entry > summary > .employee-time-entry-total:not(#nv-kit) { grid-column: 1; grid-row: 2; justify-self: start; text-align: left; white-space: nowrap; }
  html:is([data-text-step="150"], [data-text-step="200"]) body .app-shell.nevora-portal[data-employee-corporate="true"] .page-frame .employee-time-entry > summary > .employee-time-disclosure:not(#nv-kit) { grid-column: 2; grid-row: 1; }
}
